for t in range(v): blocks.append(tuple(sorted([t,(t+2)%v,(t+7)%v])))
from collections import Counter
pair=Counter()
for B in blocks:
    for i in range(3):
        for j in range(i+1,3): pair[tuple(sorted((B[i],B[j])))] +=1
